import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingMenuProductReplaceToFront } from '../@mappers/hikingMenuReplaces.mapper';
import {
  IHikingMenuProductReplaceCreateDto,
  IHikingMenuProductReplaceDeleteDto,
  IHikingMenuProductReplaceDto,
  IHikingMenuProductReplaceUpdateDto,
} from '../@types/DTO/hikingMenuReplaces.dto.types';

export const addHikingMenuProductsReplace = async (data: IHikingMenuProductReplaceCreateDto) => {
  const res = await post(
    '/ajax/hiking/menu/products/hiking_menu_product_replaces_add.php',
    data,
  ).then<{ id: number }>(handleApiError);
  return res.id;
};

export const getHikingMenuProductsReplaces = async (id_hiking: number) => {
  const res = await get('/ajax/hiking/menu/products/hiking_menu_product_replaces_list.php', {
    id_hiking,
  }).then<IHikingMenuProductReplaceDto[]>(handleApiError);
  return res.map(mapHikingMenuProductReplaceToFront);
};

export const updateHikingMenuProductsReplace = async (data: IHikingMenuProductReplaceUpdateDto) => {
  const res = await post(
    '/ajax/hiking/menu/products/hiking_menu_product_replaces_edit.php',
    data,
  ).then<{ success: boolean }>(handleApiError);
  return res.success;
};

export const deleteHikingMenuProductsReplace = async (data: IHikingMenuProductReplaceDeleteDto) => {
  const res = await post(
    '/ajax/hiking/menu/products/hiking_menu_product_replaces_del.php',
    data,
  ).then<{ success: boolean }>(handleApiError);
  return res.success;
};
