import React from 'react';

import HikingDutyTable from '@apps/Hiking/duty/HikingDutyTable';

import type { IHikingData } from '../../../../../@types/hiking.types';

interface IDutyModalProps {
  hikingData: IHikingData;
}

const DutyModal: React.FC<IDutyModalProps> = ({ hikingData }) => {
  return (
    <div>
      <h4>Дежурства</h4>
      <HikingDutyTable id_hiking={hikingData.id} />
    </div>
  );
};

export default DutyModal;
