import React from 'react';

import PersonFill from '@pohodnik/icons/svg/People/PersonFill';
import X from '@pohodnik/icons/svg/Signs/X';
import clsx from 'clsx';

import { showRecipeModal } from '@apps/Recipes/components/RecipeOne/recipeOneHelper';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import PohInput, { InputTypes, InputSizes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row/index';
import { confirmModal } from '@ui-kit/Modal/index';

import style from './style.module.less';
import { IHikingMenuFoodWithAct } from '../../../../../@types/hikingMenu.types';

interface IHikingMenuItemProps {
  data: IHikingMenuFoodWithAct;
  onChange: (patch: Partial<IHikingMenuFoodWithAct>) => void;
  onDelete: () => void;
  onSetAssignee: () => void;
  onResetAssignee: () => void;
  count: number;
  disabled?: boolean;
  onConfirm?: () => void;
}

const HikingMenuItem: React.FC<IHikingMenuItemProps> = ({
  data,
  onChange,
  onDelete,
  onSetAssignee,
  onResetAssignee,
  count,
  disabled = false,
}) => {
  const [pct, setPct] = React.useState<number>(data.correction);

  const handleDel: React.MouseEventHandler = (e) => {
    e.preventDefault();
    e.stopPropagation();
    confirmModal(
      [
        `Точно удалить «${data.name}»`,
        data.act && `который планировался на ${data.act.name}`,
        data.act && `(${data.act.start.toLocaleString()})`,
        data.assigneeUser && `и был назначен на участника ${data.assigneeUser.name}`,
        `?`,
      ]
        .filter(Boolean)
        .join(' '),
    ).then((ok) => ok && onDelete());
  };

  return (
    <PohRow className="d-flex align-items-center justify-content-between">
      <PohCol
        sm={7}
        onClick={() => data?.id_recipe && showRecipeModal(data.id_recipe)}
        className="d-flex align-items-center"
        title={[
          `Порция:\t${data.amount}г.\t${round(data.energy, 0)} ккал\tБ: ${round(data.proteins)}\tЖ: ${round(data.fats)}\tУ: ${round(data.carbs)}`,
          `-----------`,
          data.text,
        ].join('\n')}
      >
        {/* {data.confirmDate || onConfirm ? <span*/}
        {/*    className={clsx('ms-n3 me-2', data.confirmDate ? 'text-success' : 'text-warning')}*/}
        {/*    title={data.confirmDate ? ['Блюдо утверждено', data.confirmDate.toLocaleString(), data.confirmUser].join('\n') : 'Требуется утверждение руководителем похода'}*/}
        {/*    onClick={(e) => {*/}
        {/*        e.stopPropagation();*/}
        {/*        onConfirm && onConfirm();*/}
        {/*    }}>*/}
        {/*    <small>{data.confirmDate ? <PatchCheckFill /> : <PatchExclamationFill />}</small>*/}
        {/*    </span> : null} */}
        <div className="text-nowrap text-truncate d-flex">
          <span className="text-nowrap text-truncate">{data.name} </span>
          <small>
            <PohBadge>{count}</PohBadge>
          </small>
        </div>
      </PohCol>
      <PohCol sm={5} className="d-flex align-items-center justify-content-end me-n2">
        <PohDropdown
          menu={
            <div className="pb-1 px-2 text-end">
              <small className="text-nowrap">Размер порции (%)</small>
              <PohInput
                type={InputTypes.number}
                size={InputSizes.Small}
                value={round(pct * 100).toString()}
                onChange={(changedCorrection) => setPct(+changedCorrection / 100)}
                onRealChange={(val) => onChange({ correction: +val / 100 })}
                min={10}
                max={200}
                maxLength={3}
                disabled={disabled}
                className="text-end"
              />
            </div>
          }
        >
          <span className="text-nowrap" title="Изменение размера порции">
            <span
              className={clsx('border-bottom p-1', style.editable, {
                'text-warning': pct < 0.95,
                'text-danger': pct > 1.05,
              })}
            >
              {round(pct * 100)}
            </span>
            <small>&thinsp;%</small>
          </span>
        </PohDropdown>
        {data.assigneeUser && (
          <PohAva
            src={data.assigneeUser.photo}
            alt={data.assigneeUser.name}
            className={clsx('my-n2 ms-2', style.userIcon)}
            width={24}
            onClick={(e) =>
              disabled ? undefined : e.ctrlKey || e.altKey ? onResetAssignee() : onSetAssignee()
            }
            title={`Назначено участнику ${data.assigneeUser.name}\nclick - изменить\nctrl+click - сбросить`}
          />
        )}
        {!data.assigneeUser && (
          <PohAva
            title="Назначить ответственного"
            icon={<PersonFill />}
            className={clsx('my-n2 ms-2')}
            width={24}
            onClick={(e) =>
              disabled ? undefined : e.ctrlKey || e.altKey ? onResetAssignee() : onSetAssignee()
            }
          />
        )}
        {!disabled && (
          <PohButton className="ms-2" size={ButtonSize.Small} onClick={handleDel} icon={true}>
            <X />
          </PohButton>
        )}
      </PohCol>
    </PohRow>
  );
};

export default HikingMenuItem;
