import React, { FormEvent } from 'react';

import { IProduct } from '@apps/Products/@types/products.types';
import { selectProductAsync } from '@apps/Products/components/ProductSelectModal/productSelectModalHelper';
import BGUForProduct from '@components/BGU/BGUForProduct';
import notificationHelper from '@helpers/notificationHelper';
import PohButton from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

import {
  addHikingMenuProductsReplace,
  updateHikingMenuProductsReplace,
} from '../../../@services/hikingMenuReplaces.service';
import { IHikingMenuProductReplaceCreateDto } from '../../../@types/DTO/hikingMenuReplaces.dto.types';
import { IHikingMenuProductReplace } from '../../../@types/hikingMenuReplaces.types';

interface IHikingMenuProductsReplaceEditModalProps {
  id_hiking: number;
  productReplace?: IHikingMenuProductReplace;
  onChange: (v: IHikingMenuProductReplace) => void;
}

const HikingMenuProductsReplaceEditModal: React.FC<IHikingMenuProductsReplaceEditModalProps> = ({
  id_hiking,
  productReplace,
  onChange,
}) => {
  const [data, setData] = React.useState<IHikingMenuProductReplaceCreateDto & { id: number }>({
    id: productReplace?.id ?? 0,
    id_hiking,
    id_source_product: productReplace?.sourceProduct?.id ?? 0,
    id_target_product: productReplace?.targetProduct?.id ?? 0,
    rate: productReplace?.rate ?? 1,
    comment: productReplace?.comment ?? '',
  });

  const [isSaving, setIsSaving] = React.useState(false);

  const [sourceProduct, setSourceProduct] = React.useState<IProduct | undefined>(
    productReplace?.sourceProduct,
  );
  const [targetProduct, setTargetProduct] = React.useState<IProduct | undefined>(
    productReplace?.targetProduct,
  );
  const [rate, setRate] = React.useState(
    productReplace?.rate ? productReplace.rate.toString() : '1',
  );

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      if (!sourceProduct)
        return notificationHelper.warn('Необходимо выбрать продукт который меняем');
      if (!targetProduct)
        return notificationHelper.warn('Необходимо выбрать продукт на который меняем');
      setIsSaving(true);

      if (!data.id) {
        const id = await addHikingMenuProductsReplace(data);
        onChange({
          id,
          rate: data.rate,
          comment: data.comment,
          sourceProduct,
          targetProduct,
          created: {
            date: new Date(),
            user: {
              id: 0,
              name: '',
              surname: '',
              photo: '',
            },
          },
        });
      } else if (productReplace) {
        await updateHikingMenuProductsReplace(data);
        onChange({
          ...productReplace,
          rate: data.rate,
          comment: data.comment,
          sourceProduct,
          targetProduct,
        });
      }
    } finally {
      setIsSaving(false);
    }
  };

  type T = Omit<IHikingMenuProductReplaceCreateDto, 'id_hiking'>;
  const handleInputChange =
    <K extends keyof T>(field: keyof T) =>
    async (value: T[K]) => {
      setData((fd) => ({ ...fd, [field]: value }));
    };

  return (
    <form onSubmit={handleSubmit} style={{ minWidth: '60vw' }}>
      <PohRow className="mb-3">
        <PohCol sm={2}>Продукт</PohCol>
        <PohCol sm={10}>
          <PohRow>
            <PohCol sm={6}>
              <PohInput
                label="Какой продукт меняем"
                readOnly
                defaultValue={sourceProduct?.name ?? ''}
                placeholder="Выбрать продукт"
                onClick={async () => {
                  const selectedProduct = await selectProductAsync();
                  setSourceProduct(selectedProduct);
                  handleInputChange<'id_source_product'>('id_source_product')(selectedProduct.id);
                }}
                disabled={isSaving || !!productReplace?.id}
              />
              {sourceProduct && <BGUForProduct product={sourceProduct} />}
            </PohCol>
            <PohCol sm={6}>
              <PohInput
                label="На какой продукт меняем"
                readOnly
                defaultValue={targetProduct?.name ?? ''}
                placeholder="Выбрать продукт"
                onClick={async () => {
                  const selectedProduct = await selectProductAsync();
                  setTargetProduct(selectedProduct);
                  handleInputChange<'id_target_product'>('id_target_product')(selectedProduct.id);
                }}
                disabled={isSaving}
              />
              {targetProduct && <BGUForProduct product={targetProduct} rate={parseFloat(rate)} />}
            </PohCol>
          </PohRow>
        </PohCol>
      </PohRow>
      <PohInput
        horizontal
        label="Коэффициент"
        value={rate}
        onChange={setRate}
        onRealChange={(v) => {
          handleInputChange<'rate'>('rate')(parseFloat(v));
        }}
        min={0.01}
        max={99}
        step={0.01}
        type={InputTypes.number}
        wrapperClassName="mb-2"
        disabled={isSaving}
      />
      <PohInput
        horizontal
        label="Комментарий"
        value={data.comment}
        onChange={handleInputChange<'comment'>('comment')}
        type={InputTypes.textarea}
        wrapperClassName="mb-2"
        disabled={isSaving}
      />
      <footer className="pt-4 text-end">
        <PohButton type="submit" disabled={isSaving}>
          Сохранить
        </PohButton>
      </footer>
    </form>
  );
};

export const editHikingMenuProductsReplaces = (
  id_hiking: number,
  pr?: IHikingMenuProductReplace,
): Promise<IHikingMenuProductReplace> => {
  return new Promise((res) => {
    showModal({
      title: pr ? `Редактирование замены продукта` : 'Добавление замены продукта',
      size: 'lg',

      children: (clos: () => void) => {
        return (
          <HikingMenuProductsReplaceEditModal
            id_hiking={id_hiking}
            productReplace={pr}
            onChange={(v) => {
              res(v);
              clos();
            }}
          />
        );
      },
    });
  });
};
